:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --accent: #e94560;
  --text: #eaeaea;
  --muted: #8a8fa3;
  --panel: #0f3460;
}

* { box-sizing: border-box; }

[hidden] { display: none !important; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: var(--bg);
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  color: var(--text);
  padding: 16px;
}

.card {
  background: var(--card);
  border: 4px solid var(--panel);
  border-radius: 12px;
  padding: 24px;
  width: 100%;
  max-width: 380px;
  text-align: center;
  box-shadow: 0 0 0 4px #000, 0 8px 24px rgba(0,0,0,0.5);
}

h1 {
  margin: 0 0 4px;
  font-size: 1.5rem;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--accent);
}

.subtitle {
  margin: 0 0 20px;
  color: var(--muted);
  font-size: 0.875rem;
  letter-spacing: 1px;
}

.display {
  display: flex;
  gap: 12px;
  margin-bottom: 16px;
}

.floor-display, .direction-display {
  flex: 1;
  background: var(--panel);
  border-radius: 8px;
  padding: 12px 8px;
  border: 2px solid #000;
}

.label {
  display: block;
  font-size: 0.75rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 1px;
  margin-bottom: 4px;
}

.value {
  display: block;
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--accent);
  font-variant-numeric: tabular-nums;
}

.door-area {
  position: relative;
  height: 80px;
  background: #000;
  border-radius: 8px;
  overflow: hidden;
  margin-bottom: 20px;
  border: 2px solid var(--panel);
}

.door {
  position: absolute;
  top: 0;
  width: 50%;
  height: 100%;
  background: repeating-linear-gradient(
    90deg,
    var(--muted) 0px,
    var(--muted) 4px,
    var(--panel) 4px,
    var(--panel) 8px
  );
  transition: transform 0.3s steps(4);
}

.door-left { left: 0; }
.door-right { right: 0; }

.door-area.open .door-left { transform: translateX(-100%); }
.door-area.open .door-right { transform: translateX(100%); }

.panel {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
  margin-bottom: 16px;
}

.floor-btn {
  font-family: inherit;
  font-size: 1.25rem;
  font-weight: 700;
  padding: 14px 0;
  border: 3px solid #000;
  border-radius: 8px;
  background: var(--panel);
  color: var(--text);
  cursor: pointer;
  transition: background 0.1s, transform 0.05s;
}

.floor-btn:hover { background: #1a4a7a; }
.floor-btn:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}
.floor-btn:active { transform: translateY(2px); }

.floor-btn.queued {
  background: var(--accent);
  color: #fff;
}

.floor-btn.current {
  box-shadow: inset 0 0 0 3px var(--text);
}

.hint {
  margin: 0;
  font-size: 0.8125rem;
  color: var(--muted);
  line-height: 1.4;
}

@media (max-width: 360px) {
  .card { padding: 16px; }
  h1 { font-size: 1.25rem; }
  .value { font-size: 1.5rem; }
  .floor-btn { font-size: 1.1rem; padding: 12px 0; }
}

(function () {
  'use strict';

  var MIN_FLOOR = 1;
  var MAX_FLOOR = 6;
  var TICK_MS = 1000;
  var DOOR_MS = 800;

  var state = {
    currentFloor: 1,
    direction: 'idle',
    queue: [],
    doorsOpen: false,
    busy: false
  };

  var currentFloorEl = document.getElementById('current-floor');
  var directionEl = document.getElementById('direction');
  var doorArea = document.querySelector('.door-area');
  var floorButtons = Array.prototype.slice.call(document.querySelectorAll('.floor-btn'));

  function render() {
    currentFloorEl.textContent = String(state.currentFloor);
    directionEl.textContent = state.direction === 'idle' ? 'Idle' : (state.direction === 'up' ? '▲ Up' : '▼ Down');

    floorButtons.forEach(function (btn) {
      var floor = Number(btn.dataset.floor);
      btn.classList.toggle('queued', state.queue.indexOf(floor) !== -1);
      btn.classList.toggle('current', floor === state.currentFloor);
    });

    doorArea.classList.toggle('open', state.doorsOpen);
  }

  function nextTarget() {
    if (state.queue.length === 0) return null;
    // Prefer same direction, else nearest
    var up = state.queue.filter(function (f) { return f > state.currentFloor; });
    var down = state.queue.filter(function (f) { return f < state.currentFloor; });
    if (state.direction === 'down' && down.length) return Math.max.apply(null, down);
    if (up.length) return Math.min.apply(null, up);
    if (down.length) return Math.max.apply(null, down);
    return null;
  }

  function openDoors() {
    state.doorsOpen = true;
    render();
    setTimeout(function () {
      state.doorsOpen = false;
      render();
    }, DOOR_MS);
  }

  function tick() {
    if (state.busy) return;
    var target = nextTarget();
    if (target === null) {
      state.direction = 'idle';
      render();
      return;
    }

    if (target === state.currentFloor) {
      state.queue = state.queue.filter(function (f) { return f !== target; });
      state.busy = true;
      openDoors();
      setTimeout(function () {
        state.busy = false;
        state.direction = 'idle';
        render();
      }, DOOR_MS);
      return;
    }

    state.direction = target > state.currentFloor ? 'up' : 'down';
    state.currentFloor += state.direction === 'up' ? 1 : -1;
    render();

    if (state.currentFloor === target) {
      state.queue = state.queue.filter(function (f) { return f !== target; });
      state.busy = true;
      openDoors();
      setTimeout(function () {
        state.busy = false;
        render();
      }, DOOR_MS);
    }
  }

  function queueFloor(floor) {
    if (floor < MIN_FLOOR || floor > MAX_FLOOR) return;
    if (state.queue.indexOf(floor) === -1) {
      state.queue.push(floor);
    }
    render();
  }

  floorButtons.forEach(function (btn) {
    btn.addEventListener('click', function () {
      queueFloor(Number(btn.dataset.floor));
    });
  });

  setInterval(tick, TICK_MS);
  render();
})();
